function pinned(services){var exact={cyber:0,itsvc:0,business:0,other:0},total=0;services.forEach(function(s){var b=SERVICE_MAP[s.name];if(!b&&APPLIANCE.some(function(p){return s.name.indexOf(p)===0;}))b='itsvc';if(b){exact[b]+=s.net;total+=s.net;}});return {exact:exact,total:r2(total)};}
