function fromServices(services,mix){var p=pinned(services),net=sum(services,'net'),tot={cyber:0,itsvc:0,business:0,other:0};DEPT_ORDER.forEach(function(k){tot[k]=p.exact[k];});var resid=r2(net-p.total);if(resid>0)Object.keys(mix).forEach(function(k){tot[k]+=resid*mix[k];});return {parts:DEPT_ORDER.map(function(k){return {key:k,net:Math.max(r2(tot[k]),0)};}),exact:p.total,resid:Math.max(resid,0)};}

